INSERT OR IGNORE INTO reviews (id, customer_name, customer_email, rating, what_went_well, what_to_improve, status, submitted_at, reviewed_at, published_at)
VALUES
('PUBLIC-REVIEW-001','Akosua Dapaah',NULL,5,'Smooth booking, clean car, friendly team. DriveHub GH made it easy.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-002','Kojo Annan',NULL,5,'Our company has leased two vehicles from DriveHub GH for our field staff since the start of the year. Invoicing is clear, maintenance is handled promptly, and whenever a car is due for service, a replacement is delivered the same day. It has taken a real burden off our operations team.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-003','Kwame Mensah',NULL,5,'I rented a Toyota Corolla from DriveHub GH for a week of back-to-back meetings across Accra, and it ran flawlessly. The car was spotless, the AC was ice cold, and the fuel tank was full at pickup. After years of rental cars that came with surprises, this was a relief.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-004','Abena Owusu-Ansah',NULL,5,'I landed at Kotoka after a long flight from London, and the team was already waiting with my name on a sign. The paperwork took less than ten minutes and the car was ready to go. It made my first hour back in Ghana completely stress-free.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-005','Nana Yaw Boateng',NULL,5,'What I appreciate most about DriveHub GH is the honesty. The quote I received was the price I paid, with no hidden charges, no surprise deposits, and no fine print traps. For a business that manages travel budgets, that kind of transparency is rare and valuable.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-006','Efua Asante',NULL,5,'My tyre went flat near Tema on a Sunday evening and I was a bit panicked. I called the support line and someone answered right away, and a replacement was arranged within the hour. That kind of responsiveness is why I now recommend them to all my colleagues.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('PUBLIC-REVIEW-007','Samuel Ofori-Atta',NULL,5,'We hired an SUV from DriveHub GH for a family trip to Cape Coast and Kakum National Park. The car was spacious, comfortable and well maintained, and they were happy to extend the booking by a day when we wanted to stay longer. The kids loved the ride, and we loved how easy it all was.',NULL,'approved',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
